begin;
create temporary table plant_loft_before_care on commit drop as select id,data-'care'-'suitability_notes' as commercial from public.plant_loft_products;
update public.plant_loft_products set data=data||'{"care": {"profile_id": "plant-01", "light": "Bright indirect light; tolerates lower light.", "watering": "Allow the mix to dry before watering; drain completely.", "difficulty": "Lower routine care.", "pet_safety": "Toxic to cats and dogs; prevent chewing.", "sources": ["https://plants.ces.ncsu.edu/plants/dracaena-trifasciata/", "https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/snake-plant"], "identity_status": "CATALOGUE_LABEL_NOT_VERIFIED", "reviewed_at": "2026-10-25"}, "suitability_notes": "Bright indirect light; tolerates lower light. Allow the mix to dry before watering; drain completely."}'::jsonb where id='plant-01';
