update public.plant_loft_products set data=data||'{"care": {"profile_id": "plant-14", "light": "Bright indirect light.", "watering": "Keep evenly moist with drainage; never saturated or fully dry.", "difficulty": "Needs warm, humid conditions.", "pet_safety": "Named Calathea is listed non-toxic to cats/dogs; confirm exact plant.", "sources": ["https://www.rhs.org.uk/plants/calathea/growing-guide", "https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/calathea"], "identity_status": "CATALOGUE_LABEL_NOT_VERIFIED", "reviewed_at": "2026-10-25"}, "suitability_notes": "Bright indirect light. Keep evenly moist with drainage; never saturated or fully dry."}'::jsonb where id='plant-14';
