do $$ begin
 assert not exists(select 1 from public.plant_loft_products p join plant_loft_before_care b using(id) where p.data-'care'-'suitability_notes' is distinct from b.commercial),'Care update changed commercial fields';
 assert (select count(*) from public.plant_loft_products where data->>'kind'='plant' and data->'care'->>'reviewed_at'='2026-10-25')=17,'All 17 profiles required';
end $$;
select 'PASS: 17 sourced profiles; prices, stock and recommendation holds unchanged' as result;
commit;
